import Darwin
import Foundation
import Testing

@testable import ReTiCAInterfaces

/// Cross-validation of the AutoInterface wire functions against fixtures generated by the real RNS
/// 1.6.0 `AutoInterface` (Vectors/generate_autointerface_fixtures.py). Spec 2026-11-10 §7.1 items 1-4.
struct AutoInterfaceCrossValidationTests {
    typealias Scope = AutoInterfaceConfig.Scope
    typealias AddressType = AutoInterfaceConfig.AddressType

    // MARK: Fixture model

    struct Fixtures: Decodable {
        struct Group: Decodable {
            let group_id_hex: String
            let scope: String
            let type: String
            let addr: String
            let bytes: String
            let group_hash: String
        }
        struct TypeFallback: Decodable { let type: String; let bytes: String }
        struct MixedCase: Decodable { let scope: String; let bytes: String }
        struct Bogus: Decodable { let scope: String; let error: String? }
        struct Ports: Decodable {
            let cfg: [String: String]
            let discovery_port: Int
            let unicast_discovery_port: Int
            let data_port: Int
        }
        struct Descope: Decodable { let `in`: String; let out: String }
        // setsockopt: [name, level, opt, hex]. sendto: [name, hex, [addr, port, flow, scope]].
        enum Call: Decodable {
            case setsockopt(level: Int, option: Int, valueHex: String)
            case sendto(datagramHex: String, host: String, port: Int, scopeID: Int)
            init(from decoder: Decoder) throws {
                var c = try decoder.unkeyedContainer()
                let kind = try c.decode(String.self)
                if kind == "setsockopt" {
                    self = .setsockopt(
                        level: try c.decode(Int.self), option: try c.decode(Int.self),
                        valueHex: try c.decode(String.self))
                } else {
                    let hex = try c.decode(String.self)
                    var a = try c.nestedUnkeyedContainer()
                    let host = try a.decode(String.self)
                    let port = try a.decode(Int.self)
                    _ = try a.decode(Int.self)
                    let scope = try a.decode(Int.self)
                    self = .sendto(datagramHex: hex, host: host, port: port, scopeID: scope)
                }
            }
        }
        struct Announce: Decodable {
            let group_id_hex: String
            let scope: String
            let type: String
            let link_local: String
            let reverse_peer: String
            let ifindex: Int
            let peer_announce: [Call]
            let reverse_announce: [Call]
        }
        struct Formatting: Decodable { let bytes: String; let ipaddress: String; let inet_ntop: String }

        let groups: [Group]
        let type_fallback: TypeFallback
        let scope_mixed_case: MixedCase
        let bogus_scope: Bogus
        let ports: [Ports]
        let descope: [Descope]
        let announce: [Announce]
        let formatting: [Formatting]
    }

    struct FixturesMissing: Error { let name: String }

    static func load() throws -> Fixtures {
        guard let url = Bundle.module.url(forResource: "autointerface_fixtures", withExtension: "json")
        else { throw FixturesMissing(name: "autointerface_fixtures.json") }
        return try JSONDecoder().decode(Fixtures.self, from: Data(contentsOf: url))
    }

    static func bytes(hex: String) -> [UInt8] {
        stride(from: 0, to: hex.count, by: 2).map {
            let s = hex.index(hex.startIndex, offsetBy: $0)
            return UInt8(hex[s..<hex.index(s, offsetBy: 2)], radix: 16)!
        }
    }

    static func hex(_ b: some Sequence<UInt8>) -> String { b.map { String(format: "%02x", $0) }.joined() }

    // MARK: Group address

    @Test func groupAddressMatchesReferenceForWholeMatrix() throws {
        let f = try Self.load()
        #expect(f.groups.count == 4 * 5 * 2)
        for g in f.groups {
            let scope = try #require(Scope(configValue: g.scope))
            let type = try #require(AddressType(rawValue: g.type))
            let id = Data(Self.bytes(hex: g.group_id_hex))
            let got = AutoInterfaceWire.groupAddress(groupID: id, scope: scope, type: type)
            #expect(Self.hex(got) == g.bytes, "\(g.group_id_hex) \(g.scope) \(g.type)")
            // The text form the reference logged is the same address.
            #expect(AutoInterfaceWire.formatIPv6(got) == Self.canonical(g.addr), "\(g.addr)")
        }
    }

    /// Python writes the text form with "{:02x}" per 16-bit group; compare through the parsed bytes.
    static func canonical(_ text: String) -> String {
        var addr = in6_addr()
        precondition(inet_pton(AF_INET6, text, &addr) == 1)
        return AutoInterfaceWire.formatIPv6(withUnsafeBytes(of: &addr) { Array($0) })
    }

    @Test func groupAddressAnchorVectors() {
        // Spec §4.1 vectors [ran].
        let def = AutoInterfaceWire.groupAddress(
            groupID: Data("reticulum".utf8), scope: .link, type: .temporary)
        #expect(def.count == 16)
        #expect(AutoInterfaceWire.formatIPv6(def) == "ff12:0:d70b:fb1c:16e4:5e39:485e:31e1")
        #expect(def[0] == 0xff && def[1] == 0x12)
        let test = AutoInterfaceWire.groupAddress(
            groupID: Data("testgroup".utf8), scope: .link, type: .temporary)
        #expect(AutoInterfaceWire.formatIPv6(test) == "ff12:0:aa67:38a6:434:4ae8:6ee3:36ad")
        let site = AutoInterfaceWire.groupAddress(
            groupID: Data("reticulum".utf8), scope: .site, type: .temporary)
        #expect(AutoInterfaceWire.formatIPv6(site) == "ff15:0:d70b:fb1c:16e4:5e39:485e:31e1")
        let glob = AutoInterfaceWire.groupAddress(
            groupID: Data("reticulum".utf8), scope: .global, type: .permanent)
        #expect(AutoInterfaceWire.formatIPv6(glob) == "ff0e:0:d70b:fb1c:16e4:5e39:485e:31e1")
    }

    @Test func unknownAddressTypeFallsBackToTemporaryAndScopeIsCaseInsensitive() throws {
        let f = try Self.load()
        let t = AddressType(configValue: f.type_fallback.type)
        #expect(t == .temporary)
        let got = AutoInterfaceWire.groupAddress(groupID: AutoInterfaceWire.defaultGroupID, scope: .link, type: t)
        #expect(Self.hex(got) == f.type_fallback.bytes)

        let scope = try #require(Scope(configValue: f.scope_mixed_case.scope))
        #expect(scope == .site)
        let site = AutoInterfaceWire.groupAddress(groupID: AutoInterfaceWire.defaultGroupID, scope: scope, type: .temporary)
        #expect(Self.hex(site) == f.scope_mixed_case.bytes)
    }

    @Test func unknownScopeIsRejectedWhereTheReferenceCrashes() throws {
        let f = try Self.load()
        #expect(f.bogus_scope.scope == "bogus")
        #expect(f.bogus_scope.error != nil)  // the reference constructor raised
        #expect(Scope(configValue: f.bogus_scope.scope) == nil)  // ours rejects at parse time
        #expect(Scope(configValue: "") == nil)
        #expect(Scope.allCases.count == 5)
    }

    @Test func portsMatchReference() throws {
        let f = try Self.load()
        for p in f.ports {
            let cfg = AutoInterfaceConfig(
                discoveryPort: p.cfg["discovery_port"].flatMap { UInt16($0) } ?? AutoInterfaceWire.defaultDiscoveryPort,
                dataPort: p.cfg["data_port"].flatMap { UInt16($0) } ?? AutoInterfaceWire.defaultDataPort)
            #expect(Int(cfg.discoveryPort) == p.discovery_port)
            #expect(Int(cfg.unicastDiscoveryPort) == p.unicast_discovery_port)
            #expect(Int(cfg.dataPort) == p.data_port)
        }
        #expect(AutoInterfaceConfig().peerCap == 64)
        #expect(AutoInterfaceConfig().groupID == Data("reticulum".utf8))
    }

    // MARK: Descoping

    @Test func descopeMatchesReference() throws {
        let f = try Self.load()
        #expect(f.descope.count >= 6)
        for d in f.descope { #expect(AutoInterfaceWire.descope(d.in) == d.out, "\(d.in)") }
    }

    @Test func descopeQuirksAreReproduced() {
        // Spec §4.3.4.
        #expect(AutoInterfaceWire.descope("fe80:4:0:0:a::") == "fe80:4:0:0:a::")
        #expect(AutoInterfaceWire.descope("fe80:ab::1%en0") == "fe80::1")
        #expect(AutoInterfaceWire.descope("fe80::1%en0") == "fe80::1")
    }

    // MARK: Discovery token

    @Test func discoveryTokenAnchor() {
        // Spec §4.2 vector [ran].
        let t = AutoInterfaceWire.discoveryToken(groupID: Data("reticulum".utf8), linkLocal: "fe80::1")
        #expect(t.count == 32)
        #expect(Self.hex(t) == "97b25576749ea936b0d8a8536ffaf442d157cf47d460dcf13c48b7bd18b6c163")
    }

    @Test func discoveryTokenMatchesRecordedDatagrams() throws {
        let f = try Self.load()
        #expect(f.announce.count == 6)
        for a in f.announce {
            let id = Data(Self.bytes(hex: a.group_id_hex))
            let scope = try #require(Scope(configValue: a.scope))
            let type = try #require(AddressType(rawValue: a.type))
            let token = Self.hex(AutoInterfaceWire.discoveryToken(groupID: id, linkLocal: AutoInterfaceWire.descope(a.link_local)))
            let group = AutoInterfaceWire.formatIPv6(AutoInterfaceWire.groupAddress(groupID: id, scope: scope, type: type))

            // peer_announce: IPV6_MULTICAST_IF = 41, 9, index LE, then sendto(token, (group, port, 0, 0)).
            #expect(a.peer_announce.count == 2)
            guard case .setsockopt(let level, let option, let value) = a.peer_announce[0] else {
                Issue.record("expected setsockopt first"); continue
            }
            #expect(level == 41 && option == 9)  // IPPROTO_IPV6, IPV6_MULTICAST_IF on Darwin
            #expect(Int(IPPROTO_IPV6) == level && Int(IPV6_MULTICAST_IF) == option)
            #expect(value == Self.hex(withUnsafeBytes(of: UInt32(a.ifindex).littleEndian) { Array($0) }))
            guard case .sendto(let dg, let host, let port, let scopeID) = a.peer_announce[1] else {
                Issue.record("expected sendto"); continue
            }
            #expect(dg == token)
            #expect(Self.canonical(host) == group)
            #expect(port == 29716 && scopeID == 0)

            // reverse_announce: unicast to the peer on discovery_port + 1, scope = ifindex, no setsockopt.
            #expect(a.reverse_announce.count == 1)
            guard case .sendto(let rdg, let rhost, let rport, let rscope) = a.reverse_announce[0] else {
                Issue.record("expected sendto"); continue
            }
            #expect(rdg == token)
            #expect(rhost == a.reverse_peer)
            #expect(rport == 29717 && rscope == a.ifindex)
            #expect(Int(AutoInterfaceConfig().unicastDiscoveryPort) == rport)
        }
    }

    // MARK: Formatting

    @Test func formatIPv6MatchesPythonIpaddressAndInetNtop() throws {
        let f = try Self.load()
        #expect(f.formatting.count >= 30)
        for c in f.formatting {
            #expect(c.ipaddress == c.inet_ntop)
            #expect(AutoInterfaceWire.formatIPv6(Self.bytes(hex: c.bytes)) == c.ipaddress, "\(c.bytes)")
        }
    }

    @Test func formatIPv6RejectsWrongLength() {
        #expect(AutoInterfaceWire.formatIPv6([1, 2, 3]).isEmpty)
        #expect(AutoInterfaceWire.formatIPv6([]).isEmpty)
    }
}
